window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9d778f5d94422b0d"]={"versions": [{"id": "FIG-9d778f5d94422b0d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Diagramm (Software &amp; Systems Process Engineering Metamodel) zur Darstellung einer methodischen Prozessaktivität im Rahmen der AUTOSAR-Methodik (Methodology). Es beschreibt die Aktivität zur Generierung von End-to-End-Absicherungs-Wrappern (E2E Protection Wrapper) an der Schnittstelle zwischen Software-Komponentenentwicklung und Basissoftware-Design auf Basis des Virtual Functional Bus (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Task Definition):</strong>\n<ul class=\"fig-list\"><li><code>Generate E2E Protection Wrapper</code>\n</li></ul>\n</li><li><strong>Rollen (Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>Basic Software Designer</code> (führt die Aktivität aus, Beziehung: <code>«performs»</code>)\n</li><li><code>Software Component Developer</code> (optionale Ausführung mit Multiplizität <code>0..1</code>, Beziehung: <code>«performs»</code>)\n</li></ul>\n</li><li><strong>Eingangsartefakte (Input Work Products):</strong>\n<ul class=\"fig-list\"><li><code>E2E Protection Set</code> (Multiplizität <code>1</code>, Beziehung: <code>«input»</code>)\n</li><li><code>VFB System</code> (Multiplizität <code>1</code>, Beziehung: <code>«input»</code>; aggregiert via <code>«SPEM_Aggregation»</code> mit Kardinalität <code>0..*</code> Artefakte vom Typ <code>E2E Protection Set</code>)\n</li><li>Unbenanntes Dokument-/Beschreibungsartefakt unten links (Multiplizität <code>1</code>, Beziehung: <code>«input»</code>)\n</li></ul>\n</li><li><strong>Ausgangsartefakte (Output Work Products):</strong>\n<ul class=\"fig-list\"><li><code>E2E Protection Wrapper Header File</code> (Multiplizität <code>1</code>, Beziehung: <code>«output»</code>)\n</li><li><code>E2E Protection Wrapper Source Code</code> (Multiplizität <code>1</code>, Beziehung: <code>«output»</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Rollen <code>Basic Software Designer</code> und/oder <code>Software Component Developer</code> initiieren die Aktivität <code>Generate E2E Protection Wrapper</code>.\n</li><li>Als Eingangsdaten werden die Systemspezifikation <code>VFB System</code>, das zugehörige <code>E2E Protection Set</code> sowie die ergänzende Systemspezifikation konsumiert.\n</li><li>Die Aktivität erzeugt als deterministisches Ergebnis den Sourcecode (<code>E2E Protection Wrapper Source Code</code>) sowie die zugehörige Header-Datei (<code>E2E Protection Wrapper Header File</code>) für den Wrapper.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der E2E Protection Wrapper kapselt E2E-Schutzmechanismen (wie z. B. CRC-Berechnung, Alive-Counter) für VFB-Kommunikationsbeziehungen ab, ohne den Anwendungscode der Software-Komponente direkt an die E2E-Bibliothek binden zu müssen.\n</li><li>Die Ausführung kann abhängig vom organisatorischen Prozessentwurf entweder durch den Basissoftware-Entwickler oder komponentenbezogen durch den Software Component Developer erfolgen.\n</li><li>Generierte Header- und Quellcodedateien müssen in den Build- und Integrationsprozess der jeweiligen ECU bzw. SWC eingebunden werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7ebd806a2781ea94", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-Diagramm (Software &amp; Systems Process Engineering Metamodel) zur Darstellung einer methodischen Prozessaktivität im Rahmen der AUTOSAR-Methodik (Methodology). Es beschreibt die Aktivität zur Generierung von End-to-End-Absicherungs-Wrappern (E2E Protection Wrapper) an der Schnittstelle zwischen Software-Komponentenentwicklung und Basissoftware-Design auf Basis des Virtual Functional Bus (VFB).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität (Task Definition):</strong>\n<ul class=\"fig-list\"><li><code>Generate E2E Protection Wrapper</code>\n</li></ul>\n</li><li><strong>Rollen (Process Roles):</strong>\n<ul class=\"fig-list\"><li><code>Basic Software Designer</code> (führt die Aktivität aus, Beziehung: <code>«performs»</code>)\n</li><li><code>Software Component Developer</code> (optionale Ausführung mit Multiplizität <code>0..1</code>, Beziehung: <code>«performs»</code>)\n</li></ul>\n</li><li><strong>Eingangsartefakte (Input Work Products):</strong>\n<ul class=\"fig-list\"><li><code>E2E Protection Set</code> (Multiplizität <code>1</code>, Beziehung: <code>«input»</code>)\n</li><li><code>VFB System</code> (Multiplizität <code>1</code>, Beziehung: <code>«input»</code>; aggregiert via <code>«SPEM_Aggregation»</code> mit Kardinalität <code>0..*</code> Artefakte vom Typ <code>E2E Protection Set</code>)\n</li><li>Unbenanntes Dokument-/Beschreibungsartefakt unten links (Multiplizität <code>1</code>, Beziehung: <code>«input»</code>)\n</li></ul>\n</li><li><strong>Ausgangsartefakte (Output Work Products):</strong>\n<ul class=\"fig-list\"><li><code>E2E Protection Wrapper Header File</code> (Multiplizität <code>1</code>, Beziehung: <code>«output»</code>)\n</li><li><code>E2E Protection Wrapper Source Code</code> (Multiplizität <code>1</code>, Beziehung: <code>«output»</code>)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Rollen <code>Basic Software Designer</code> und/oder <code>Software Component Developer</code> initiieren die Aktivität <code>Generate E2E Protection Wrapper</code>.\n</li><li>Als Eingangsdaten werden die Systemspezifikation <code>VFB System</code>, das zugehörige <code>E2E Protection Set</code> sowie die ergänzende Systemspezifikation konsumiert.\n</li><li>Die Aktivität erzeugt als deterministisches Ergebnis den Sourcecode (<code>E2E Protection Wrapper Source Code</code>) sowie die zugehörige Header-Datei (<code>E2E Protection Wrapper Header File</code>) für den Wrapper.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Der E2E Protection Wrapper kapselt E2E-Schutzmechanismen (wie z. B. CRC-Berechnung, Alive-Counter) für VFB-Kommunikationsbeziehungen ab, ohne den Anwendungscode der Software-Komponente direkt an die E2E-Bibliothek binden zu müssen.\n</li><li>Die Ausführung kann abhängig vom organisatorischen Prozessentwurf entweder durch den Basissoftware-Entwickler oder komponentenbezogen durch den Software Component Developer erfolgen.\n</li><li>Generierte Header- und Quellcodedateien müssen in den Build- und Integrationsprozess der jeweiligen ECU bzw. SWC eingebunden werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-9d778f5d94422b0d", "to": "FIG-7ebd806a2781ea94", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
